BINARY_EXTENSIONS = {'.png', '.jpg', '.jpeg', '.gif', '.ico', '.bmp', '.webp',
                     '.zip', '.tar', '.gz', '.bz2', '.xz', '.rar', '.7z',
                     '.exe', '.bin', '.so', '.whl', '.dll', '.dylib', '.pyc',
