    try:
        while True:
            try:
                logs = get_logs(session_id, after_id=last_id, conn=_poll_conn)
                _idle_ticks = 0 if logs else _idle_ticks + 1
                for log in logs:
                    if log["id"] <= last_id:
                        continue
                    last_id = log["id"]
                    t, c = log["type"], log["content"]
                    if t in ("text", "tool"):
                        await _update_topic_status(orch_name, True)
                    if t == "user_message":
